// PlatformUsers is the resolver for the platformUsers field.
func (r *queryResolver) PlatformUsers(ctx context.Context, search *string, appRole *string, tenantID *string, branchID *string) ([]*model.User, error) {
	if err := r.Resolver.requirePlatformAdmin(ctx); err != nil {
		return nil, err
	}
	svcUsers, err := r.UserService.ListUsers(ctx, nil)
	if err != nil {
		return nil, err
	}

	// Branch/client filter: collect the user IDs assigned anywhere in scope.
	// A branch narrows to its own assignments; a client unions every branch.
	allowedIDs := map[string]bool{}
	if (branchID != nil && *branchID != "") || (tenantID != nil && *tenantID != "") {
		branchIDs := []string{}
		if branchID != nil && *branchID != "" {
			branchIDs = []string{*branchID}
		} else {
			branches, err := r.TenantService.ListBranchesByTenant(ctx, *tenantID)
			if err != nil {
				return nil, err
			}
			for _, b := range branches {
				branchIDs = append(branchIDs, b.ID)
			}
		}
		for _, bid := range branchIDs {
			assignments, err := r.TenantService.ListAssignmentsByBranch(ctx, bid)
			if err != nil {
				return nil, err
			}
			for _, a := range assignments {
				allowedIDs[a.UserID] = true
			}
		}
	}

	out := make([]*model.User, 0, len(svcUsers))
	for _, svcUser := range svcUsers {
		u, err := r.Resolver.userFromSvc(ctx, svcUser)
		if err != nil {
			return nil, err
		}
		if search != nil && *search != "" && !matchUserSearch(u, *search) {
			continue
		}
		if appRole != nil && *appRole != "" && !hasAppRoleName(u, *appRole) {
			continue
		}
		if len(allowedIDs) > 0 && !allowedIDs[u.ID] {
			continue
		}
		out = append(out, u)
	}
	return out, nil
}

